<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['category_id']??0);$label=trim($_POST['label']??'');$key=trim($_POST['field_key']??'');$type=$_POST['input_type']??'text';$allowed=['text','textarea','number','select','multiselect','boolean','year'];if($id&&$label&&preg_match('/^[a-z][a-z0-9_]*$/',$key)&&in_array($type,$allowed,true)){$options=array_filter(array_map('trim',preg_split('/\r?\n/',$_POST['options']??'')));$q=db()->prepare('INSERT INTO category_fields(category_id,field_key,label,input_type,options_json,unit,sort_order) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE label=VALUES(label),input_type=VALUES(input_type),options_json=VALUES(options_json),unit=VALUES(unit),sort_order=VALUES(sort_order)');$q->execute([$id,$key,$label,$type,json_encode(array_values($options)),$_POST['unit']??null,(int)($_POST['sort_order']??100)]);flash('success','Category field saved.');}else flash('error','Please check the field details.');redirect('admin/categories/index.php');}
$cats=db()->query('SELECT * FROM project_categories ORDER BY name')->fetchAll();$fields=db()->query('SELECT f.*,c.name category_name FROM category_fields f JOIN project_categories c ON c.id=f.category_id ORDER BY c.name,f.sort_order')->fetchAll();$pageTitle='Categories & Dynamic Fields';require __DIR__.'/../../includes/admin_header.php';
?><h2>Add or update a category field</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><p><label>Category <select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label></p><p><label>Field key <input name="field_key" pattern="[a-z][a-z0-9_]*" required></label></p><p><label>Label <input name="label" required></label></p><p><label>Input type <select name="input_type"><?php foreach(['text','textarea','number','select','multiselect','boolean','year'] as $t):?><option><?=$t?></option><?php endforeach;?></select></label></p><p><label>Options (one per line) <textarea name="options"></textarea></label></p><p><label>Unit <input name="unit" placeholder="sq.ft"></label></p><p><label>Sort order <input type="number" name="sort_order" value="100"></label></p><button>Save field</button></form><h2>Existing fields</h2><table border="1" cellpadding="5"><tr><th>Category</th><th>Key</th><th>Label</th><th>Type</th><th>Active</th></tr><?php foreach($fields as $f):?><tr><td><?=e($f['category_name'])?></td><td><?=e($f['field_key'])?></td><td><?=e($f['label'])?></td><td><?=e($f['input_type'])?></td><td><?= (int)$f['is_active']?'Yes':'No'?></td></tr><?php endforeach;?></table><?php require __DIR__.'/../../includes/admin_footer.php';
